    """深拷贝嵌套 list 并把每个叶值落实为有限 float，返回全新副本。

    叶值为 int（且非 bool）时转换为 float；bool、非数值或非有限值
    分别抛 TypeError/ValueError，保证写出与重载后每个叶值均为 float。
    """
    if depth == 0:
        if isinstance(node, bool) or not isinstance(node, (int, float)):
            raise TypeError(
                "%s 的叶值必须是 float，得到 %s"
                % (name, type(node).__name__)
            )
        value = float(node)
        if not math.isfinite(value):
            raise ValueError("%s 含有非有限值（NaN/inf）" % name)
        return value
    if not isinstance(node, list):
        raise ValueError(
            "%s 的层级不足：期望 %d 层嵌套 list" % (name, depth)
        )
    return [_copy_float_tensor(child, depth - 1, name) for child in node]

