            )
        raise ValueError("linear 的键必须依次为 values、bias")

    conv_values = conv_obj["values"]
    conv_bias = conv_obj["bias"]
    lin_values = linear_obj["values"]
    lin_bias = linear_obj["bias"]
    if not isinstance(conv_values, list):
